def is_2_5_smooth(k):
    """Checks if k only has prime factors 2 and 5."""
    if k <= 0:
        return False
    while k % 2 == 0:
        k //= 2
    while k % 5 == 0:
        k //= 5
    return k == 1

def check_n_values():
    results = []
    # n >= 16, so n+2 >= 18. Max n is 1000, so max n+2 is 1002.

    # Iterate through potential n+2 values (N) that are 2/5-smooth
    # Since 1002 is the upper bound for N, we iterate up to 1002.

    for N in range(18, 1003):
        if is_2_5_smooth(N):
            n = N - 2

            # Check the second factor: (n+1)^2 + 1
            # n+1 = N-1
            inner_factor = (N - 1)**2 + 1

            if is_2_5_smooth(inner_factor):
                # Both factors are 2/5-smooth, so D(n) is 2/5-smooth.
                results.append(n)

    return results

solutions = check_n_values()
print(f"Solutions found for n >= 16 up to 1000: {solutions}")
